// Tìm pname trong danh sách (binary search trên mảng đã sort).
inline bool IsAcceptedPname(uint32_t p) {
    uint32_t lo = 0, hi = kAcceptedPnameCount;
    while (lo < hi) {
        uint32_t mid = lo + (hi - lo) / 2;
        uint32_t v = kAcceptedPnames[mid];
        if (v == p) return true;
        if (v < p) lo = mid + 1; else hi = mid;
    }
    return false;
}

